import sys
import json

input_data = {}
try:
    input_data = json.loads(sys.argv[1])
except Exception:
    pass

x = input_data.get("x", 15)
y = input_data.get("y", 41)

x = int(x)
y = int(y)

buttons = []

if (x, y) == (15, 41):
    buttons = ["Left", "Up", "Right", "Down"]
elif (x, y) == (14, 41):
    buttons = ["Up", "Right", "Down", "Left"]
elif (x, y) == (14, 40):
    buttons = ["Right", "Down", "Left", "Up"]
elif (x, y) == (15, 40):
    buttons = ["Down", "Left", "Up", "Right"]
else:
    if x < 15:
        buttons.append("Right")
    elif x > 15:
        buttons.append("Left")

    if y < 41:
        buttons.append("Down")
    elif y > 41:
        buttons.append("Up")

print(json.dumps(buttons))
